#!/usr/bin/env python3
"""Build deterministic, bounded evidence summary from verified saved output."""
from pressure_fin import *
def main():
    d=json.loads((HERE/'design_results.json').read_text());v=json.loads((HERE/'verification.json').read_text());s=json.loads((HERE/'sensitivity_results.json').read_text());base_d=next(x for x in d['designs'] if x['design_id']=='n16_t860');bc={x['case_id']:x for x in base_d['cases']};nom=bc['nominal'];comb=bc['combined_fault']
    for r in s['rows']:
        r['G_change_from_primary_percent']=(r['G_W_K']/bc[r['case_id']]['G_W_K']-1)*100;r['Tb_at_60W_C']=25+60/r['G_W_K']
    save('sensitivity_results.json',s)
    passed=[x['design_id'] for x in d['designs'] if next(c['conditional_screen_pass'] for c in x['cases'] if c['case_id']=='combined_fault')]
    nominal_passed=[x['design_id'] for x in d['designs'] if next(c['conditional_screen_pass'] for c in x['cases'] if c['case_id']=='nominal')]
    scope=[x['design_id'] for x in d['designs'] if x['all_cases_within_declared_Re_scope']];pareto=[x['design_id'] for x in d['designs'] if x['pareto_within_Re_scope']]
    summary={'scope':'declared synthetic component-scale screening exercise; not aircraft validation','numerical_verification_passed':v['status']=='passed','all_design_gates_passed':d['all_numerical_gates_pass'],'all_sensitivity_gates_passed':s['all_numerical_gates_pass'],'design_count':len(d['designs']),'design_scenario_count':sum(len(x['cases']) for x in d['designs']),'sensitivity_run_count':len(s['rows']),'maximum_omitted_viscous_dissipation_fraction_of_60W':max(c['pressure_dissipation_W']/60 for x in d['designs'] for c in x['cases']),'within_declared_Re_scope_design_ids':scope,'nominal_conditional_screen_pass_design_ids':nominal_passed,'combined_conditional_screen_pass_design_ids':passed,'pareto_within_Re_scope_design_ids':pareto,'baseline':{'fin_only_mass_g':base_d['fin_only_mass_g'],'nominal_G_W_K':nom['G_W_K'],'combined_G_W_K':comb['G_W_K'],'nominal_Tb_at_60W_C':nom['Tb_at_60W_C'],'combined_Tb_at_60W_C':comb['Tb_at_60W_C'],'nominal_flow_kg_s':nom['mass_flow_kg_s'],'combined_flow_kg_s':comb['mass_flow_kg_s'],'nominal_pressure_dissipation_W':nom['pressure_dissipation_W'],'combined_pressure_dissipation_W':comb['pressure_dissipation_W'],'nominal_side_flow_fraction':nom['side_channel_flow_fraction'],'combined_side_flow_fraction':comb['side_channel_flow_fraction']},'grid_max_spatial_relative':max(r['spatial_G_relative'] for r in v['grid_comparisons']),'grid_max_axial_relative':max(r['axial_G_relative'] for r in v['grid_comparisons']),'caveat':'Conditional screen = numerical gates plus declared Reynolds, mass and temperature conditions. Model-form uncertainty and omitted physics remain; the screened set is not a robust or validated design recommendation.'}
    save('summary.json',summary)
    lines=['# Declared synthetic pressure/mass/fault screening results','',summary['scope']+'.','',f"Numerical verification: **{v['status']}**. All 36 design-scenario gates: **{d['all_numerical_gates_pass']}**. All 18 sensitivity gates: **{s['all_numerical_gates_pass']}**.",'','## Baseline and combined fault','',f"The baseline has 16 fins, 0.86 mm thickness, and {base_d['fin_only_mass_g']:.3f} g of fin-only aluminum. Under the declared 60 W load, the required uniform-base temperature is {nom['Tb_at_60W_C']:.2f}°C at 25 Pa and {comb['Tb_at_60W_C']:.2f}°C at 15 Pa with the first interior branch sealed. The synthetic ceiling is 85°C. This is not a local hot-spot calculation. High failed-case temperatures below are constant-property linear extrapolations, not validated high-temperature predictions.",'','| Case | Pressure (Pa) | G (W/K) | Required base at 60 W (°C) | Total flow (g/s) | Dissipation (mW) |','|---|---:|---:|---:|---:|---:|']
    for c in base_d['cases']:lines.append(f"| {c['case_id']} | {c['pressure_Pa']:.0f} | {c['G_W_K']:.5f} | {c['Tb_at_60W_C']:.2f} | {c['mass_flow_kg_s']*1000:.5f} | {c['pressure_dissipation_W']*1000:.3f} |")
    lines+=['','At fixed common pressure, branch closure changes mass fractions; open-branch absolute flows stay unchanged. The sealed fluid retains transverse conduction but has no advected inlet state. Dissipation is not electrical fan power.','', f"Viscous heat generation is omitted from the thermal PDE. Across this sweep, the reported hydraulic dissipation is at most {summary['maximum_omitted_viscous_dissipation_fraction_of_60W']*100:.3f}% of the 60 W load. Conservation gates apply to the stated thermal model, not a complete installed-system energy balance.",'', '## All nine designs retained','', '| N | Thickness (mm) | Fin mass (g) | Nominal base (°C) | Combined-fault base (°C) | Maximum nominal Re | Status |','|---:|---:|---:|---:|---:|---:|---|']
    for row in d['designs']:
        cc={r['case_id']:r for r in row['cases']};status=[]
        if not row['all_cases_within_declared_Re_scope']:status.append('outside declared Re scope')
        if not row['mass_limit_pass']:status.append('mass fails')
        if not cc['nominal']['thermal_limit_pass_60W']:status.append('nominal temperature fails')
        if not cc['combined_fault']['thermal_limit_pass_60W']:status.append('combined temperature fails')
        if cc['combined_fault']['conditional_screen_pass']:status.append('conditional combined screen pass')
        if row['dominated_by_scope_candidates']:status.append('dominated within Re scope')
        elif row['pareto_within_Re_scope']:status.append('on Re-scope Pareto set')
        lines.append(f"| {row['N_fins']} | {row['thickness_mm']:.2f} | {row['fin_only_mass_g']:.3f} | {cc['nominal']['Tb_at_60W_C']:.2f} | {cc['combined_fault']['Tb_at_60W_C']:.2f} | {cc['nominal']['max_Re_Dh']:.1f} | {'; '.join(status)} |")
    lines+=['',f"Conditional nominal passes: {', '.join(nominal_passed) or 'none'}. Conditional combined-fault passes: {', '.join(passed) or 'none'}.",'',f"The mass/combined-temperature Pareto set within the declared Reynolds scope is {', '.join(pareto) or 'empty'}. Pareto status is a relative geometric screening result, not proof of feasibility, robustness, or validation. All dominated and nonlaminar extrapolation results remain in the JSON.",'','## Numerical evidence','',f"The maximum declared spatial-pair G difference is {summary['grid_max_spatial_relative']*100:.4f}%, below 0.5%. The maximum axial-pair difference is {summary['grid_max_axial_relative']*100:.4f}%, below 0.2%. These differences are discretization indicators, not uncertainty bounds.",'','Independent limits include exact rectangular hydraulic conductance, an isothermal-fin/uniform-velocity continuum heat-equation series, a uniform-bath analytical fin, adiabatic walls, low-flow heat-capacity saturation, reflection symmetry, and pressure/branch network identities. Strict mass, pressure, wall-force, componentwise thermal, temperature-bound, and energy checks apply to the saved runs.','', '## Baseline sensitivities','', '| Case | Perturbation | G change (%) | Required base at 60 W (°C) |','|---|---|---:|---:|']
    for r in s['rows']:lines.append(f"| {r['case_id']} | {r['sensitivity_parameter']} = {r['sensitivity_value']} | {r['G_change_from_primary_percent']:+.3f} | {r['Tb_at_60W_C']:.2f} |")
    lines+=['','These are illustrative baseline-only sensitivity scenarios, not confidence bounds. Plug flow holds the pressure-derived mean flux fixed and changes only the thermal advection profile; it is not a valid no-slip momentum solution. Its sensitivity cannot be used to declare uncertain alternatives physically validated.','', '## Limits and provenance','', 'Read README.md and presweep_plan.json for the full boundary/omission ledger. Key limits are the fixed-temperature base, assumed fully developed laminar velocity, omitted inlet/outlet/development losses, no contact/base/axial-solid conduction, constant properties, and the ideal branch-sealing fault. No aircraft validation or new experimental comparison is claimed.','', 'The plan precedes these new numerical runs but follows the earlier experimental campaign. No requirements or coefficients were chosen after inspecting this sweep. The original experimental model and freeze were not changed.','', 'Every JSON is below 100 kB and every binary is checked below 250 kB. Original source-input hashes and all study artifact hashes are recorded in manifest.json.']
    (HERE/'RESULTS.md').write_text('\n'.join(lines)+'\n')
    source_paths=[SOURCE,HERE.parent/'fin-study/precomparison_plan.json',HERE.parent/'fin-study/verification.json',HERE.parent/'fin-study/review/final_review_gate.json'];entries=[]
    for p in sorted(HERE.rglob('*')):
        if p.is_file() and p.name not in ('manifest.json','summary.log'):
            size=p.stat().st_size
            if p.suffix=='.json' and size>=100000:raise ValueError(f'JSON limit: {p}')
            if p.suffix in ('.png','.pyc','.pdf','.npy','.npz') and size>=250000:raise ValueError(f'binary limit: {p}')
            entries.append({'file':str(p.relative_to(HERE)),'bytes':size,'sha256':digest(p)})
    save('manifest.json',{'scope':'study artifacts only; inherited inputs read-only','original_inputs':[{'file':str(p.relative_to(HERE.parent)),'sha256':digest(p)} for p in source_paths],'artifacts':entries,'all_file_limits_passed':True})
    print(json.dumps(summary,indent=2))
if __name__=='__main__':main()
